def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Convert the list of tuples into a grid
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Dynamic programming function to find the maximum sum on one path
    @lru_cache(None)
    def max_path_sum(x: int, y: int, visited: set) -> int:
        if x == N-1 and y == N-1:
            return grid[x][y]
        if x >= N or y >= N or (x, y) in visited:
            return 0
        visited.add((x, y))
        max_sum = 0
        for dx, dy in [(1, 0), (0, 1)]:
            max_sum = max(max_sum, max_path_sum(x + dx, y + dy, visited))
        visited.remove((x, y))
        return grid[x][y] + max_sum

    # Iterate over all possible starting points of the second path
    max_sum = 0
    for x in range(N):
        for y in range(N):
            visited = set()
            first_path_sum = max_path_sum(0, 0, visited)
            second_path_sum = max_path_sum(x, y, visited)
            max_sum = max(max_sum, first_path_sum + second_path_sum)

    return max_sum

