def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from heapq import heappop, heappush

    # Build the grid
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if value == 0:
            break
        grid[x-1][y-1] = value

    # Define the directions for moving in the grid
    directions = [(0, 1), (1, 0)]

    # Initialize the max heap
    max_heap = []
    heappush(max_heap, (grid[0][0], 0, 0))

    # Array to store the maximum value at each cell
    max_values = [[-1] * N for _ in range(N)]
    max_values[0][0] = grid[0][0]

    while len(max_heap) > 0:
        current_value, x, y = heappop(max_heap)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and max_values[nx][ny] == -1:
                max_values[nx][ny] = current_value + grid[nx][ny]
                heappush(max_heap, (max_values[nx][ny], nx, ny))

    # Find the maximum value collected on two paths
    max_sum = 0
    for i in range(N):
        for j in range(N):
            if i + j == N - 1:
                max_sum = max(max_sum, max_values[i][j])

    return max_sum

