    # Initialize a 3D list to store the maximum value up to each point and each path
    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

    # Iterate over each value to place in the grid
    for x, y, value in grid_values:
        if x == 0 and y == 0:
