def find_number_combinations():
    valid_combinations = []
    digits = set('123456789')

    for num1 in range(100, 1000):
        str1 = str(num1)
        if len(set(str1)) != 3 or not set(str1) <= digits:
            continue

        num2 = num1 * 2
        num3 = num1 * 3

        str2 = str(num2)
        str3 = str(num3)

        if len(set(str2)) != 3 or not set(str2) <= digits:
            continue
        if len(set(str3)) != 3 or not set(str3) <= digits:
            continue

        if len(set(str1 + str2 + str3)) == 9 and len(set(str1) & set(str2) & set(str3)) == 0:
            valid_combinations.append((num1, num2, num3))

    return sorted(valid_combinations)

