    from collections import deque

    visited = set()
    queue = deque([n])

    while queue:
        current = queue.popleft()
        if current not in visited:
            visited.add(current)
            current_str = str(current)
            for i, char in enumerate(current_str):
                digit = int(char)
                for old_digit, new_digit in rules:
                    if digit == old_digit:
                        new_number = int(current_str[:i] + str(new_digit) + current_str[i+1:])
                        if new_number not in visited:
                            queue.append(new_number)

    return len(visited)

