def generate_numbers(n, rules) -> int:
    from collections import deque

    # Convert the number to a string for easy manipulation
    n_str = str(n)
    # Initialize a set to keep track of unique numbers
    unique_numbers = {n}
    # Initialize a queue for BFS
    queue = deque([n_str])

    while queue:
        current_str = queue.popleft()
        # Try each transformation rule
        for x, y in rules:
            # Replace each occurrence of x with y in the current string
            for i in range(len(current_str)):
                if current_str[i] == str(x):
                    new_str = current_str[:i] + str(y) + current_str[i+1:]
                    # Convert the new string back to an integer
                    new_num = int(new_str)
                    # If the new number is not already in the set, add it
                    if new_num not in unique_numbers:
                        unique_numbers.add(new_num)
                        queue.append(new_str)

    # Return the count of unique numbers
    return len(unique_numbers)

