def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Separate statements into liars and truth-tellers
    liar_statements = {participant: stmt for participant, stmt in statements.items() if participant in liar_count}
    truth_teller_statements = {participant: stmt for participant, stmt in statements.items() if participant not in liar_count}

    # Check statements from liars
    for liar, stmts in liar_statements.items():
        for stmt in stmts:
            if scenario != liar and "is guilty" in stmt:
                return False
            if scenario == liar and "is guilty" not in stmt:
                return False

    # Check statements from truth-tellers
    for truth_teller, stmts in truth_teller_statements.items():
        for stmt in stmts:
            if scenario != truth_teller and "is guilty" in stmt:
                return False
            if scenario == truth_teller and "is guilty" not in stmt:
                return False

    return True

