def catalan_number(n: int) -> int:
    if n == 0:
        return 1

    # Initialize the list to store Catalan numbers
    catalan = [0] * (n + 1)
    catalan[0] = 1  # base case

    # Compute the Catalan numbers using the recursive formula
    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - 1 - j]

    return catalan[n]

