def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.

    Args:
    heights (List[int]): A list of student heights.

    Returns:
    int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n <= 2:
        return 0

    dp_increase = [1] * n
    dp_decrease = [1] * n

    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            dp_increase[i] = dp_increase[i - 1] + 1

    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            dp_decrease[i] = dp_decrease[i + 1] + 1

    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, dp_increase[i] + dp_decrease[i] - 1)

    return n - max_choir_length

