def hanoi_double_iterative(n: int) -> int:
    # Base case: if there is only one pair of discs, return 2 moves
    if n == 1:
        return 2

    # Initialize the result with the base case value
    result = 2

    # Iteratively compute the number of moves for n pairs of discs
    for i in range(2, n + 1):
        result = 2 * result + 2

    return result

